import{R as e,e as o,f as r,U as n}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"SugarCRM","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/sugarcrm.md","filePath":"integrations/crm/sugarcrm.md","lastUpdated":1775908585000}'),a={name:"integrations/crm/sugarcrm.md"};function i(l,t,s,c,g,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="sugarcrm" tabindex="-1">SugarCRM <a class="header-anchor" href="#sugarcrm" aria-label="Permalink to &quot;SugarCRM&quot;">​</a></h1><p>Follow the below steps to connect to the SugarCRM API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select SugarCRM as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-sugarcrm-api" tabindex="-1">Step 2. Connect to the SugarCRM API <a class="header-anchor" href="#step-2-connect-to-the-sugarcrm-api" aria-label="Permalink to &quot;Step 2. Connect to the SugarCRM API&quot;">​</a></h3><ol><li>Go to <a href="https://sugarcrm.com/" target="_blank">SugarCRM</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Admin</strong>.</li><li>Find and click the <strong>Configure API Platforms</strong> link.</li><li>Below the table of API Platforms, enter <code>formie</code> in the add field, and click the <strong>Add</strong> button. This will add <code>formie</code> to the table of platforms.</li><li>Enter the username for your SugarCRM account in the <strong>Username</strong> field in Formie.</li><li>Enter the password for your SugarCRM account in the <strong>Password</strong> field in Formie.</li><li>Enter the full domain (including <code>https://</code>) for your SugarCRM account in the <strong>Domain</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(a,[["render",i]]);export{u as __pageData,m as default};
